!function(e){function t(t){for(var r,i,o=t[0],m=t[1],d=t[2],g=0,_=[];g<o.length;g++)i=o[g],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&_.push(n[i][0]),n[i]=0;for(r in m)Object.prototype.hasOwnProperty.call(m,r)&&(e[r]=m[r]);for(c&&c(t);_.length;)_.shift()();return p.push.apply(p,d||[]),a()}function a(){for(var e,t=0;t<p.length;t++){for(var a,i=p[t],o=!0,m=1;m<i.length;m++)a=i[m],0!==n[a]&&(o=!1);o&&(p.splice(t--,1),e=r(r.s=i[0]))}return e}function r(t){if(i[t])return i[t].exports;var a=i[t]={i:t,l:!1,exports:{}};return e[t].call(a.exports,a,a.exports,r),a.l=!0,a.exports}var i={},n={25:0},p=[];r.m=e,r.c=i,r.d=function(e,t,a){r.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:a})},r.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},r.t=function(e,t){if(1&t&&(e=r(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var a=Object.create(null);if(r.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)r.d(a,i,function(t){return e[t]}.bind(null,i));return a},r.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return r.d(t,"a",t),t},r.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},r.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=t,o=o.slice();for(var d=0;d<o.length;d++)t(o[d]);var c=m;p.push([112,0]),a()}({112:function(e,t,a){"use strict";a.r(t);var r=a(0);Object(r.a)("de","army",a(113),a(1))},113:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"253型半履带装甲炮兵观测车","description":"<p>253型是二战德军最早生产的一种半履带装甲车，是专门配备给二战早期的Ⅲ号突击炮部队，作为突击炮营指挥官在战场上观测Ⅲ号突击炮的战场状况并进行战斗指挥的一种炮兵观测车，有时也会担负战场的侦察任务。253在1940年4月开始生产，至1941年6月共生产了285辆，但因为该车车体较小，车内空间狭窄造成车内人员活动不便，更由于Ⅲ号突击炮的指挥官经常要乘车亲临战场侦察、观测和指挥，而该型车装甲薄弱，又无武器配备，在战场上极容易被击毁，1941年德军入侵巴尔干半岛，253型半履带装甲炮兵观测车第一次参战，在实战中，就突出地反映了该车的生存能力严重不足，因此使用部队对253感到很不满意；后来随着250与251系列的同类功能的改装车出现，253车很快就停止装备突击炮部队。而余下的253型半履带装甲炮兵观测车后来装备了德军的摩托化炮兵部队，专用于炮兵部队在前沿观测用。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}253型半履带装甲炮兵观测车四视图（线图）{{image}}imgs/de/army/de_army_avhtv253_11.jpg{{caption}}注意：该型车车顶用钢板密封，车长位置上方是圆形对开舱门，车长可打开舱门探出车顶对外观察；车顶另一个方形舱门则是供通讯员出入。车厢前有2个供驾驶员观察的窗口。","description":"<h6>253型半履带装甲炮兵观测车</h6><p>性能参数：</p><p>车长：4.70m，车宽：1.95m，车高：1.80m，战斗全重：5.78t；</p><p>最大时速（公路）：65KM/h，最大行程（公路）：175km；</p><p>装甲厚度（车顶与后部钢板）：8mm；</p><p>装备：1台FuG Spr型短距离联络电台和1台FuG 7（或FuG 12）大功率电台（通讯距离50km）；</p><p>武器配备：1挺MG34机枪（早期253并未专门配备武器，只是车组成员为了拥有自卫手段，在车厢内放置了一挺MG34机枪；需用时就拿出舱口使用；但后期一些253已将机枪固定安装在指挥舱口前）。</p>","caption":""}],"part2title":"战场上的253型半履带装甲炮兵观测车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv253_21.jpg","description":"1941年夏天，东线苏联战场，德军第2装甲师第74摩托化炮兵团第3炮兵连的一辆253型半履带装甲炮兵观测车。车顶的横杆是2米天线的卧轨，与天线基座相连。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_22.jpg","description":"1941年，非洲战场利比亚，德军第5轻装师第5装甲团第2营营部所属的一辆253型半履带装甲炮兵观测车。车上安装了框形天线。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_23.jpg","description":"1941年4月，南斯拉夫战场，德军第197突击炮营第2连所属的一辆253型半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_24.jpg","description":"1942年，非洲战场利比亚，德军第21装甲师第155炮兵团所属的一辆253型半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_25.jpg","description":"1942年9月，东线苏联战场斯大林格勒地区，隶属德军第24装甲师第89摩托化炮兵团的一辆253型半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_26.jpg","description":"1943年夏季，东线苏联战场，隶属德军“大德意志”装甲掷弹兵师“GD”摩托化炮兵团的一辆253型半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_27.jpg","description":"1943年，东线苏联战场，隶属德军第197突击炮营的一辆253型半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_28.jpg","description":"1944年夏季，东线战场，隶属德军第4装甲师第103炮兵团的一辆253型半履带装甲炮兵观测车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_29.jpg","description":"1942年夏季，东线苏联战场，配备给德军突击炮部队的一辆253型半履带装甲炮兵观测车正与德军Ⅲ号突击炮一起向前线进发。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_30.jpg","description":"1942年夏季，东线苏联战场，德军第11装甲师第118炮兵团的一辆253型半履带装甲炮兵观测车正在战场上指挥德军Ⅲ号突击炮部队作战。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_31.jpg","description":"1941年，北非战场，德国非洲军团最高指挥官隆美尔元帅正站在一辆253型半履带装甲炮兵观测车前对一德军军官作指示。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_32.jpg","description":"1941年6月，东线苏联战场，德军一辆253型半履带装甲炮兵观测车的指挥官正站在车顶观察分析战场情况。配备给突击炮部队的253装甲车的车长通常是突击炮连（或排）的指挥官。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_33.jpg","description":"1942年夏季，东线苏联战场，一辆253型半履带装甲炮兵观测车正在向前线进发。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_34.jpg","description":"一辆在北非战场上的德军253型半履带装甲炮兵观测车，一挺MG34机枪安装在车顶的圆形舱口前，由一名车组成员（车长）操纵，车上使用的是FuG 12型大功率电台，安装的是框形天线。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_35.jpg","description":"隶属于德军第191突击炮营的一辆253型半履带装甲炮兵观测车，车上安装了一挺带防盾的MG34型机枪。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_36.jpg","description":"1941年7月，东线苏联战场，一辆253型半履带装甲炮兵观测车正在向前线疾驶前进，后面跟着的是一辆德军Ⅲ号突击炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_37.jpg","description":"1942年，东线苏联战场，一辆253型半履带装甲炮兵观测车正在与德军步兵一起在某城市街道上向前挺进。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_38.jpg","description":"1941年，德军入侵巴尔干，在希腊战场，一辆253型半履带装甲炮兵观测车内的德军Ⅲ号突击炮部队指挥官在车外正在开会商研战场态势。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_39.jpg","description":"1942年夏季，东线苏联战场，一辆253型半履带装甲炮兵观测车正在战斗中前进。该车的机枪采用德军中型坦克炮塔高射机枪的安装形式，虽然没有防盾，但竖起的舱口盖钢板却可起到防弹作用。","caption":""},{"image":"imgs/de/army/de_army_avhtv253_40.jpg","description":"1941年，行进在巴尔干半岛的险峻山间中的一辆德军第197突击炮营的253型半履带装甲炮兵观测车，车上可清楚见到车顶的车长舱口和通讯员舱口都各站着一位车组乘员。","caption":""}]}')}});